(function () {
    const DEFAULT_TIMEOUT = 10000;

    function loadScript(url, timeout) {
        return new Promise((resolve, reject) => {
            const existing = document.querySelector(`script[src="${url}"]`);
            if (existing) {
                resolve();
                return;
            }

            const script = document.createElement("script");
            const timer = window.setTimeout(() => {
                script.remove();
                reject(new Error("Script load timeout: " + url));
            }, timeout);

            script.src = url;
            script.async = true;
            script.onload = () => {
                window.clearTimeout(timer);
                resolve();
            };
            script.onerror = () => {
                window.clearTimeout(timer);
                script.remove();
                reject(new Error("Script load failed: " + url));
            };
            document.head.appendChild(script);
        });
    }

    function loadStyle(url, timeout) {
        return new Promise((resolve, reject) => {
            const existing = document.querySelector(`link[href="${url}"]`);
            if (existing) {
                resolve();
                return;
            }

            const link = document.createElement("link");
            const timer = window.setTimeout(() => {
                link.remove();
                reject(new Error("Style load timeout: " + url));
            }, timeout);

            link.rel = "stylesheet";
            link.href = url;
            link.onload = () => {
                window.clearTimeout(timer);
                resolve();
            };
            link.onerror = () => {
                window.clearTimeout(timer);
                link.remove();
                reject(new Error("Style load failed: " + url));
            };
            document.head.appendChild(link);
        });
    }

    function normalizeTacConfig(tac) {
        if (typeof tac === "string") {
            return { url: tac };
        }
        return Object.assign({}, tac);
    }

    function loadTAC(tac, captchaConfig, captchaStyle) {
        return new Promise((resolve, reject) => {
            const options = normalizeTacConfig(tac);
            const baseUrl = options.url
                || options.baseUrl
                || "/tac";
            const normalizedBase = baseUrl.endsWith("/")
                ? baseUrl
                : baseUrl + "/";
            const timeout = options.timeout || DEFAULT_TIMEOUT;
            const scriptUrls = options.scriptUrls
                || [normalizedBase + "js/tac.min.js"];
            const cssUrls = options.cssUrls
                || [normalizedBase + "css/tac.css"];

            Promise.all([
                ...scriptUrls.map((url) => loadScript(url, timeout)),
                ...cssUrls.map((url) => loadStyle(url, timeout))
            ]).then(() => {
                if (typeof window.TAC !== "function") {
                    reject(new Error("TAC not loaded"));
                    return;
                }
                resolve(new window.TAC(captchaConfig, captchaStyle));
            }).catch(reject);
        });
    }

    window.loadTAC = loadTAC;
    window.initTAC = loadTAC;
})();
